<?php defined('ABSPATH') || exit;$logo=absint(frpmt_option('footer_logo_id')); ?><footer class="frpmt-footer"><?php if($logo)echo wp_get_attachment_image($logo,'medium',false,array('alt'=>get_bloginfo('name'))); ?><p><?php echo esc_html(frpmt_option('footer_description')?:get_bloginfo('description')); ?></p><?php if(frpmt_option('footer_copyright')): ?><small><?php echo esc_html(frpmt_option('footer_copyright')); ?></small><?php else: ?><small>&copy; <?php echo esc_html(date_i18n('Y')); ?> <?php echo esc_html(get_bloginfo('name')); ?></small><?php endif; ?></footer>
